ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	status: "HEALTHY",
	service: "Asset Allocation MCP Server",
	version: "${mcp.server.version}",
	timestamp: now(),
	environment: "${env}",
	checks: [
		{
			name: "database",
			status: vars.dbStatus
		},
		{
			name: "application", 
			status: "UP"
		}
	],
	uptime: 3600,
	features: {
		mockMode: ("${mcp.features.mock.enabled}" as Boolean),
		databaseRequired: true
	}
}

%dw 2.0
output application/json
---
{
	status: "DEGRADED",
	service: "Asset Allocation MCP Server",
	version: "${mcp.server.version}",
	timestamp: now(),
	environment: "${env}",
	checks: [
		{
			name: "database",
			status: "DOWN"
		},
		{
			name: "application",
			status: "UP"
		}
	],
	uptime: 3600,
	features: {
		mockMode: true,
		databaseRequired: true
	}
}

%dw 2.0
output application/json
---
{
	name: "Asset Allocation MCP Server",
	version: "${mcp.server.version}",
	description: "Intelligent IT asset management capabilities for employee onboarding processes",
	baseUrl: "${mcp.server.baseUrl}",
	environment: "${env}",
	capabilities: {
		assetAllocation: true,
		assetReturn: true,
		assetListing: true,
		employeeAssets: true,
		healthMonitoring: true,
		mockMode: ("${mcp.features.mock.enabled}" as Boolean)
	},
	endpoints: {
		health: "/api/health",
		allocateAssets: "/api/allocate-assets",
		returnAsset: "/api/return-asset",
		listAssets: "/api/list-assets",
		availableAssets: "/api/get-available-assets",
		employeeAssets: "/api/get-employee-assets"
	},
	tools: [
		{
			name: "allocate-assets",
			description: "Allocate available assets to employees"
		},
		{
			name: "return-asset", 
			description: "Return allocated assets to available pool"
		},
		{
			name: "list-assets",
			description: "List and filter assets by status and category"
		},
		{
			name: "get-employee-assets",
			description: "Get all assets allocated to a specific employee"
		}
	]
}

db:update.db:input-parameters:
